let wait_for_device_preview_email_runs ~since ?email_domain_id ?profile_id ?local_part ?(limit = 20l) ?(timeout_millis = 25000L) ?(poll_interval_millis = 1000L) ?(hydrate_thumbnail = false) () =
    let open Lwt in
    let uri = Request.build_uri "/emails/device-previews/email-runs/wait" in
    let headers = Request.default_headers in
    let headers = Cohttp.Header.add headers "x-api-key" Request.api_key in
    let uri = Request.add_query_param uri "since" (fun x -> x) since in
    let uri = Request.maybe_add_query_param uri "emailDomainId"  email_domain_id in
    let uri = Request.maybe_add_query_param uri "profileId"  profile_id in
    let uri = Request.maybe_add_query_param uri "localPart" (fun x -> x) local_part in
    let uri = Request.add_query_param uri "limit" Int32.to_string limit in
    let uri = Request.add_query_param uri "timeoutMillis" Int64.to_string timeout_millis in
    let uri = Request.add_query_param uri "pollIntervalMillis" Int64.to_string poll_interval_millis in
    let uri = Request.add_query_param uri "hydrateThumbnail" string_of_bool hydrate_thumbnail in
    Cohttp_lwt_unix.Client.call `GET uri ~headers >>= fun (resp, body) ->
    Request.read_json_body_as (JsonSupport.unwrap Device_preview_ingest_run_wait_result.of_yojson) resp body

